    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values

    (v_aula_id, 1, $p$Visto que as Escrituras nunca elogiam um pastor que não discipula e só aplaudem pastores reprodutores, em quem você está deliberadamente investindo para que a liderança continue na próxima geração?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Aplicando os quatro princípios de Jesus (meditação com oração, seleção com critério, associação com propósito e proclamação com poder), qual deles está ausente na maneira como você forma discípulos?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Assim como Moisés discipulou Josué e Elias discipulou Eliseu, você tem se reproduzido em outros, ou tem tentado suportar sozinho as cargas que deveria compartilhar?$p$, 'reflexao', null);
