    (v_aula_id, 1, $p$Refletindo sobre o conselho de construir o ministério em torno das Escrituras desde o início, que padrão de estudo diligente e pregação você está estabelecendo agora para colher frutos pelo resto da vida?$p$, 'reflexao', null),
